window.MG_LAZY_DATA["data/lazy/resources/security-v26-097-6e4b76a50ee5364f.json"]={sha256:"6e4b76a50ee5364fdfa5f713400cbfaca806fccf7259ef8ffbda76984b3476ed",value:{"sources":[{"id":"v26-case-b105a845c1ae4f9e","url":"https://docs.aws.amazon.com/AmazonS3/latest/userguide/object-lock.html","title":"Amazon S3 Object Lock","titleEn":"Amazon S3 Object Lock","publisher":"AWS","scope":"查證具名案例與原理背景。課內數值、故障資料與判準為原創教學假設；請勿當作廠商規格或操作程序。","scopeEn":"Establish named case and principle context. Numbers, fault data, and criteria are original teaching assumptions, not manufacturer specifications or operating procedures."}],"media":{"courses":[{"courseId":"security-v26-097","videos":[],"guides":[]}]},"related":{"courses":[{"courseId":"security-v26-097","related":[{"id":"security-v26-098","referenceUrls":["https://csrc.nist.gov/pubs/sp/800/34/r1/upd1/final"],"title":"NIST BIA：RTO、RPO與服務復原目標","titleEn":"NIST BIA: RTO, RPO and service recovery objectives","why":"用兩課的可觀察驗收條件比較模型邊界：交付版本保留表、60GB容量估算、版本查找測試與復原驗證計畫。","whyEn":"Compare model boundaries using observable acceptance criteria: Deliver version-retention records, sixty-GB estimate, version-lookup tests and restore-validation plan.","difference":"分開最大可容忍中斷、RTO與RPO，列出資料重建成本及必要外部相依。","differenceEn":"Distinguish maximum tolerable disruption, RTO and RPO, recording data reconstruction cost and external dependencies.","transfer":"保留單位與邊界條件，僅轉移可證明相容的驗證方法。","transferEn":"Retain units and boundary conditions; transfer only demonstrably compatible verification methods.","practice":["固定保留容量估算=每日新增不可變資料×保留天數；版本與重複備份會增加容量，鎖定不等於已驗證可復原。 以下為自編合成案例，只在自己的離線文件、測試資料或明確授權的隔離環境演練；不是產品實測或生產設定。 每日新增2GB合成備份版本，固定保留30天，假設無壓縮與去重。 穩態最低保留量2×30=60GB，不含額外副本與中繼資料。","最壞資料時間損失可用成功備份間隔作簡化上界，但必須考慮備份失敗；RTO另含還原與驗證。 以下為自編合成案例，只在自己的離線文件、測試資料或明確授權的隔離環境演練；不是產品實測或生產設定。 目標RPO15分鐘、RTO90分鐘；本簡化模型假設中斷立即被偵測並宣告，無額外等待。備份每10分鐘成功一次，還原50分鐘、驗證25分鐘、切換10分鐘。 理想RPO上界10分鐘符合15；復原總85分鐘，距RTO剩5分鐘裕度。","比較兩個模型的輸入、誤差與驗收條件，記錄不能沿用的假設。"],"practiceEn":["Fixed-retention capacity is new immutable data per day times days; versions add storage, and locking does not prove recoverability. This original synthetic case uses owned offline files, test data or an explicitly authorized isolated lab; it is not a product benchmark or a production configuration. Two GB of synthetic backup versions are added daily with thirty-day fixed retention and no compression or deduplication. Steady-state retained data is at least 60 GB, excluding extra copies and metadata.","A successful backup interval can approximate a worst-case data-time loss bound, but failures matter; RTO separately includes restore and validation. This original synthetic case uses owned offline files, test data or an explicitly authorized isolated lab; it is not a product benchmark or a production configuration. Targets are RPO fifteen minutes and RTO ninety minutes; this simplified model assumes immediate detection and declaration at disruption, with no extra waiting. Successful backups occur every ten minutes, with fifty-minute restore, twenty-five-minute validation and ten-minute cutover. Ideal RPO bound is ten minutes, meeting fifteen; recovery totals eighty-five minutes with five minutes of RTO margin.","Compare inputs, errors, and criteria; document assumptions that cannot be transferred."]},{"id":"security-v26-007","referenceUrls":["https://www.rfc-editor.org/rfc/rfc9700.html"],"title":"OAuth 2.0 安全實務：PKCE 與權杖生命週期","titleEn":"OAuth 2.0 security: PKCE and token lifecycles","why":"用兩課的可觀察驗收條件比較模型邊界：交付版本保留表、60GB容量估算、版本查找測試與復原驗證計畫。","whyEn":"Compare model boundaries using observable acceptance criteria: Deliver version-retention records, sixty-GB estimate, version-lookup tests and restore-validation plan.","difference":"用紙面序列圖串接授權碼、S256 PKCE challenge、verifier與token端點；在圖上標出state、精確redirect URI與refresh token輪替的不同功能。","differenceEn":"Draw the authorization code, S256 PKCE challenge, verifier and token endpoint; distinguish state, exact redirect URI and refresh-token rotation.","transfer":"保留單位與邊界條件，僅轉移可證明相容的驗證方法。","transferEn":"Retain units and boundary conditions; transfer only demonstrably compatible verification methods.","practice":["固定保留容量估算=每日新增不可變資料×保留天數；版本與重複備份會增加容量，鎖定不等於已驗證可復原。 以下為自編合成案例，只在自己的離線文件、測試資料或明確授權的隔離環境演練；不是產品實測或生產設定。 每日新增2GB合成備份版本，固定保留30天，假設無壓縮與去重。 穩態最低保留量2×30=60GB，不含額外副本與中繼資料。","PKCE將授權碼兌換綁到verifier；若verifier由均勻隨機位元組產生，原始熵上限為8n位元，但不等於整個系統安全強度。 教學verifier來源為32個獨立均勻隨機位元組，再做無填補base64url編碼；不使用可預測時間戳。 原始熵32×8=256位元；48位元組版本為384位元。編碼長度分別43與64字元，編碼不創造額外熵。","比較兩個模型的輸入、誤差與驗收條件，記錄不能沿用的假設。"],"practiceEn":["Fixed-retention capacity is new immutable data per day times days; versions add storage, and locking does not prove recoverability. This original synthetic case uses owned offline files, test data or an explicitly authorized isolated lab; it is not a product benchmark or a production configuration. Two GB of synthetic backup versions are added daily with thirty-day fixed retention and no compression or deduplication. Steady-state retained data is at least 60 GB, excluding extra copies and metadata.","PKCE binds code redemption to a verifier; n uniformly random bytes provide at most 8n bits of source entropy, not the strength of the entire system. The teaching verifier starts with 32 independent uniform random bytes and uses unpadded base64url, not predictable timestamps. Source entropy is 32×8=256 bits; 48 bytes provide 384 bits. Encoded lengths are 43 and 64 characters; encoding adds no entropy.","Compare inputs, errors, and criteria; document assumptions that cannot be transferred."]}],"references":[{"id":"v26-case-f561a6295e1b6a09","url":"https://csrc.nist.gov/pubs/sp/800/34/r1/upd1/final","title":"NIST SP 800-34r1 contingency planning","titleEn":"NIST SP 800-34r1 contingency planning","publisher":"NIST","scope":"查證具名案例與原理背景。課內數值、故障資料與判準為原創教學假設；請勿當作廠商規格或操作程序。","scopeEn":"Establish named case and principle context. Numbers, fault data, and criteria are original teaching assumptions, not manufacturer specifications or operating procedures."},{"id":"v26-case-4e6d674bf887d330","url":"https://www.rfc-editor.org/rfc/rfc9700.html","title":"RFC 9700: Best Current Practice for OAuth 2.0 Security","titleEn":"RFC 9700: Best Current Practice for OAuth 2.0 Security","publisher":"IETF","scope":"查證具名案例與原理背景。課內數值、故障資料與判準為原創教學假設；請勿當作廠商規格或操作程序。","scopeEn":"Establish named case and principle context. Numbers, fault data, and criteria are original teaching assumptions, not manufacturer specifications or operating procedures."}],"overview":"比較相鄰案例與另一組案例的模型、可量測結果及可轉移的驗證方法。","overviewEn":"Compare neighboring and cross-group cases by model, measurable outcome, and transferable verification method."}]},"places":{"courses":[]},"vendors":{"courses":[],"vendors":[]}}};
